import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates based on t-statistics and effect sizes
    candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('copy_number', 'expression'):
            t_stat = feats.x[:, i].T @ (feats.y * 2 - 1) / (np.std(feats.x[:, i]) * np.sqrt(len(feats.y)))
            effect_size = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
            candidates.append((fid, abs(t_stat), abs(effect_size)))

    # Sort by t-statistic magnitude
    candidates.sort(key=lambda x: x[1], reverse=True)

    # Remove near-duplicates (correlated features)
    selected = []
    used = set()
    for fid, _, _ in candidates:
        if fid in used:
            continue
        selected.append(fid)
        used.add(fid)
        # Mark correlated features as used
        for other_fid, corr in [(f, r) for f, r in zip(feats.ids, np.corrcoef(feats.x.T)[feats.column(fid)]) 
                               if abs(r) >= 0.6 and f != fid]:
            used.add(other_fid)
        if len(selected) >= MAX_DRIVERS:
            break

    # Check for interaction terms among top candidates
    interactions = []
    for i, a in enumerate(selected):
        for b in selected[i+1:]:
            # Compute interaction term
            col_a = feats.column(a)
            col_b = feats.column(b)
            interaction = feats.x[:, col_a] * feats.x[:, col_b]

            # Test if interaction improves prediction
            cor_with_outcome = np.corrcoef(interaction, feats.y)[0, 1]
            if abs(cor_with_outcome) > 0.05:
                interactions.append((a, b))

    # If we found interactions, return them
    if interactions:
        a, b = interactions[0]
        return Design(
            drivers=(a, b),
            columns=(a, b),
            products=((a, b),),
            loadings={a: 1.0, b: 1.0}
        )

    # Otherwise, return top single features
    if selected:
        return Design(
            drivers=(selected[0],),
            columns=(selected[0],),
            products=(),
            loadings={selected[0]: 1.0}
        )

    # No mechanism found
    return Design(drivers=(), columns=(), products=(), loadings={})

